const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([140.878144, 27.245974]);
  const buffer = point.buffer(2000); // 2 km radius
  const date = '2013-12-08';
  const startDate = '2013-12-01';
  const endDate = '2013-12-31';

  // 2. Data Acquisition - Landsat 8 Surface Reflectance
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(point)
    .filterDate(startDate, endDate)
    .sort('CLOUD_COVER');

  // Check if collection is empty
  const collectionSize = collection.size().getInfo();
  console.log(`Images in December 2013: ${collectionSize}`);

  if (collectionSize === 0) {
    // No Landsat 8 images, try Landsat 7? But Landsat 8 started in 2013 and should have data.
    // However, if no data, we output C1.
    console.log('No Landsat 8 images found in December 2013.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get the least cloudy image
  const image = collection.first();
  const cloudCover = image.get('CLOUD_COVER').getInfo();
  console.log(`Selected image cloud cover: ${cloudCover}%`);

  // 3. Cloud Masking for Landsat 8
  const qa = image.select('QA_PIXEL');
  const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)  // Cloud bit (3)
    .and(qa.bitwiseAnd(1 << 4).eq(0)); // Cloud shadow bit (4)
  const maskedImage = image.updateMask(cloudMask);

  // 4. Compute NDWI and create land/water mask
  // Landsat 8 bands: Green = B3, NIR = B5
  const ndwi = maskedImage.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
  // Water: NDWI > 0, Land: NDWI <= 0
  const landMask = ndwi.lt(0); // 1 for land, 0 for water

  // 5. Check valid pixel count (after cloud masking) in the buffer
  const validCount = ndwi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9,
  }).get('NDWI').getInfo();
  console.log(`Valid pixels in buffer: ${validCount}`);

  if (validCount === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Count land pixels
  const landPixelCount = landMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9,
  }).get('constant').getInfo();
  console.log(`Land pixels in buffer: ${landPixelCount}`);

  // 7. Connected components to find distinct islands
  const connected = landMask.connectedComponents({
    connectedness: ee.Kernel.plus(1),
    maxSize: 128,
  });
  // Mask out water (label 0) to only keep land components
  const islands = connected.updateMask(connected.neq(0));

  // Count distinct non-zero labels (islands)
  const distinctLabels = islands.reduceRegion({
    reducer: ee.Reducer.countDistinct(),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9,
  }).get('labels').getInfo();

  const islandCount = distinctLabels || 0; // If distinctLabels is null, set to 0
  console.log(`Number of islands: ${islandCount}`);

  // 8. Validation & Final Answer
  // Check if islandCount is exactly 2
  if (islandCount === 2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
